package com.textbook.orders.client;

import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;

// ANTI-PATTERN AVOIDED: We never inject a second DataSource into OrderService.
// Instead, we use a dedicated API client to fetch data from the owning service over HTTP/gRPC.
@FeignClient(name = "inventory-service", url = "${inventory.service.url}")
public interface InventoryClient {

    @GetMapping("/api/inventory/{productId}")
    InventoryDTO getInventoryLevel(@PathVariable("productId") Long productId);
}
